        plt.ylabel('Speed per Bout (cm/s, Mean \u00b1 SEM)')
        plt.grid(False)
        ax = plt.gca()
        ax.tick_params(axis='both', direction='in')
        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
