                    _ax.set_ylabel('Treadmill Speed (cm/s)' if _ci == 0 else '')
                    _ax.set_xlim(-0.6, 1.6)
                    _ax.tick_params(axis='both', direction='in')
                    _ax.spines['top'].set_visible(False)
